"""E2E for the LangSmith-style UI (P0/P1): pages load without JS errors, key controls work."""
from playwright.sync_api import sync_playwright
c = dict(l.split("=", 1) for l in open("/workspace/secrets/deepagent_web.txt").read().split()); U = c["url"].rstrip("/")
R = {}
def ok(n, cond, extra=""): R[n] = bool(cond); print(("PASS " if cond else "FAIL ") + n, "|", str(extra)[:200], flush=True)
with sync_playwright() as p:
    b = p.chromium.launch(executable_path="/usr/bin/google-chrome", args=["--no-sandbox"]); ctx = b.new_context(viewport={"width": 1440, "height": 900}); pg = ctx.new_page()
    errs = []; pg.on("pageerror", lambda e: errs.append(str(e)))
    pg.goto(U + "/login"); pg.fill("#u", "moza"); pg.fill("#p", c["password"]); pg.click("form button"); pg.wait_for_timeout(3000)
    pg.evaluate("()=>fetch('api/auth/lang',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lang:'en'})})"); ctx.add_cookies([{"name": "aos_lang", "value": "en", "url": U}])
    def go(path, sel, name):
        errs.clear(); pg.goto(U + path, wait_until="networkidle"); pg.wait_for_timeout(2000)
        ok(f"{name} renders", pg.locator(sel).count() > 0 and not errs, errs[:2])
    # shell
    go("/overview", "#sb nav a", "shell sidebar")
    labels = pg.locator("#sb nav > a .lb").all_inner_texts()
    ok("sidebar order matches spec", labels[:16] == ["Engine", "Studio", "Build", "Tracing", "Monitoring", "Datasets & Experiments", "Evaluations", "Annotation Queues", "Prompts", "Playground", "Deployments", "Context Hub", "Dashboards", "Custom Apps", "LLM Gateway", "Sandboxes"], labels[:16])
    ok("WORKSPACE section header", "WORKSPACE" in pg.inner_text("#sb nav").upper())
    ok("no PLUS paywall badges", "PLUS" not in pg.inner_text("#sb"))
    ok("top bar Search/Ask/Invite", pg.locator("#ckbtn").count() == 1 and pg.locator("#askbtn").count() == 1 and "Invite your team" in pg.inner_text("#tb"))
    pg.click("#newag"); pg.wait_for_timeout(500); mt = pg.inner_text("body")
    ok("+Agent menu BUILD/CONNECT", all(x in mt for x in ["Without code", "With code", "Trace an existing agent"]))
    pg.get_by_text("Trace an existing agent").click(); pg.wait_for_timeout(800); ok("Connect an agent slide-over", "Connect an agent" in pg.inner_text("body") and pg.locator("text=Agent ID").count() > 0)
    pg.keyboard.press("Escape"); pg.goto(U + "/overview", wait_until="networkidle")
    pg.click("#ubtn"); pg.wait_for_timeout(400); um = pg.inner_text("body"); ok("user menu items", all(x in um for x in ["Invitations", "Documentation", "Get help", "Log out"])); pg.keyboard.press("Escape")
    pg.keyboard.press("Control+k"); pg.wait_for_timeout(500); ok("⌘K palette opens", pg.locator("#ck.on").count() == 1); pg.keyboard.press("Escape")
    ok("Inter font served locally", pg.evaluate("()=>fetch('static/fonts/inter-latin-wght-normal.woff2').then(r=>r.ok)"))
    ok("Macaw MIT notice served", "MIT" in pg.evaluate("()=>fetch('static/licenses/Macaw-MIT.txt').then(r=>r.text())"))
    pg.click("#thbtn"); ok("dark mode toggles html.dark", pg.evaluate("()=>document.documentElement.classList.contains('dark')")); pg.click("#thbtn")
    ok("no emoji in sidebar", not any(ord(ch) > 0x2600 for ch in "".join(labels)))
    # tracing
    go("/projects?p=1", "#rb tr.r", "Tracing table")
    ok("Threads/Traces/Runs toggle", pg.locator("#mode button").all_inner_texts() == ["Threads", "Traces", "Runs"])
    n0 = pg.locator("#rb tr.r").count()
    pg.click("#addf"); pg.select_option("#fa", "status"); pg.select_option("#fo", "eq"); pg.fill("#fv", "error"); pg.click("#fok"); pg.wait_for_timeout(2500)
    ok("filter chip added and applied", pg.locator(".fchip").count() == 1 and pg.locator("#rb tr.r").count() != n0 or pg.locator("#rb .empty").count() == 1, pg.locator("#rb tr.r").count())
    pg.locator(".fchip button").click(); pg.wait_for_timeout(2000)
    pg.on("dialog", lambda d: d.accept("ui-test-view"))
    pg.click("#saveas"); pg.wait_for_timeout(2000); ok("saved view created", "ui-test-view" in pg.inner_text("#vname"))
    pg.click("#vbtn"); pg.wait_for_timeout(500); pg.locator(".menu.pop [data-del]").last.click(); pg.wait_for_timeout(1500); ok("saved view deleted", "Default View" in pg.inner_text("#vname"))
    pg.locator("#rb .rk").first.check(); pg.wait_for_timeout(300); ok("bulk action bar appears", pg.locator("#bulk.on").count() == 1, pg.inner_text("#bn")); pg.click("#bx")
    pg.locator("#rb tr.r td:nth-child(3)").first.click(); pg.wait_for_timeout(2500)
    ok("trace slide-over opens", pg.locator("#pane.on").count() == 1)
    ok("run tabs Feedback/Input/Output/Attributes", pg.locator("[data-rt]").all_inner_texts() == ["Feedback", "Input", "Output", "Attributes"])
    ok("views Trajectory/Turns/Details", pg.locator("#pview button").all_inner_texts() == ["Trajectory", "Turns", "Details"])
    pg.click("#wfb"); pg.wait_for_timeout(300); ok("waterfall bars", pg.locator(".wf").count() > 0)
    pg.click("#pview [data-v=turns]"); pg.wait_for_timeout(500); ok("turns view", pg.locator(".turn").count() > 0)
    pg.click("#pview [data-v=trajectory]"); pg.wait_for_timeout(500); ok("trajectory view", pg.locator(".traj").count() == 1 and not errs, errs[:1])
    pg.click("#pclose"); pg.click("#mode [data-m=threads]"); pg.wait_for_timeout(2500); ok("threads table", pg.locator("#rb tr.r[data-th]").count() > 0)
    for t in ["engine", "automations", "evaluators", "insights"]:
        errs.clear(); pg.click(f"#ptabs [data-t={t}]"); pg.wait_for_timeout(2500); ok(f"project tab {t}", not errs and "Loading" not in pg.inner_text("#tab_other"), errs[:1])
    # P1 pages
    go("/overview?agent=1", ".mrow", "Agent Overview metrics")
    ok("4 environments", pg.locator(".tl table tbody tr").count() == 4)
    go("/monitoring?p=1", ".ccard", "Monitoring dashboards")
    go("/datasets", "table tbody tr.r", "Datasets list")
    go("/datasets?d=1&tab=examples", "table", "Dataset examples tab")
    go("/hub", "#pt tr.r", "Prompts table")
    go("/hub?id=1", ".cm", "Prompt commit history")
    go("/playground", ".msgc", "Playground message cards")
    go("/deployments", "table", "Deployments list")
    go("/settings?s=members", "table", "Settings members")
    go("/settings?s=keys", "table", "Settings API keys")
    go("/listeners", ".card table", "Listeners page (in More)")
    ok("Listeners lives under More", pg.locator("#sb details.more a[href='listeners']").count() == 1)
    # steering pages
    go("/overview?welcome=1", "#wyes", "All agents empty-state cards"); ok("two onboarding cards", "Yes, I have one" in pg.inner_text("body") and "starting fresh" in pg.inner_text("body"))
    go("/engine", ".kpi", "Engine page")
    go("/builder", "#b", "Build page"); ok("Build search + New agent", pg.locator("input[placeholder='Search agents...']").count() == 1)
    go("/evaluators", "table", "Evaluations page"); ok("Evaluator/Columns tabs", "Columns" in pg.inner_text("#h"))
    go("/annotation", "table", "Annotation Queues page"); ok("Assigned to me filter", "Assigned to me" in pg.inner_text("body"))
    go("/context", "#b", "Context Hub page"); ok("Context tabs", all(x in pg.inner_text("body") for x in ["Agents", "Skills", "Private", "Public"]))
    go("/dashboards", "table", "Dashboards page")
    go("/apps", ".steps", "Custom Apps tutorial")
    go("/gateway", ".prov", "LLM Gateway page"); ok("gateway code tabs", all(x in pg.inner_text("body") for x in ["cURL", "Python", "TypeScript", "Anthropic"]))
    go("/sandboxes", "table", "Sandboxes page")
    go("/datasets?view=experiment", "#dh", "Experiment tab"); ok("Dataset|Experiment tabs", pg.locator("[data-lt]").all_inner_texts() == ["Dataset", "Experiment"])
    go("/datasets", "table", "Datasets columns"); ok("dataset columns", all(x in pg.inner_text("thead") for x in ["Last Experiment", "Updated At", "Created At"]))
    go("/datasets?new_experiment=1", ".steps", "New experiment page"); ok("Python/TypeScript tabs, 5 steps", pg.locator("[data-lg2]").count() == 2 and pg.locator(".steps > div").count() == 5)
    go("/hub?webhook=1", "#xpane.on", "Prompt webhook slide-over"); ok("webhook triggers + sample payload", "Sample payload" in pg.inner_text("#xpane") and pg.locator("#wtt").count() == 1)
    ok("All Prompts dropdown", pg.locator("#pf option").count() >= 2)
    go("/playground", "#nxb tr", "Playground experiment table"); ok("Prompts/Inputs/Output layout", all(x.upper() in pg.inner_text("body").upper() for x in ["Prompts", "Inputs", "Output", "New Experiment"]))
    go("/deployments?cli=1", ".steps", "Deployments CLI flow")
    go("/settings?s=engine", ".donut", "Settings Engine donut")
    go("/settings?s=usage", ".bars", "Settings Usage graph"); ok("granular usage filters", pg.locator("#ua").count() == 1 and pg.locator("#ug").count() == 1)
    ok("settings nav groups", all(x.upper() in pg.inner_text("#setnav").upper() for x in ["Back to Agent OS", "Access and Security", "Integrations", "Workspace", "Usage", "Model pricing", "MCP servers"]))
    pg.click("#ssb"); pg.wait_for_timeout(300); pg.fill("#smq", "pricing"); pg.wait_for_timeout(200); pg.keyboard.press("Enter"); pg.wait_for_timeout(1500)
    ok("settings search modal navigates", "s=pricing" in pg.url and "Price / 1M input" in pg.inner_text("#sc"), pg.url)
    for s2 in ["mcp", "models", "webhooks", "secrets", "fbtags", "restags", "oauth", "integrations", "aisearch"]:
        go(f"/settings?s={s2}", "#sc .phead", f"settings {s2}")
    go("/projects?tab=engine", "#tab_other table", "Engine via sidebar")
    go("/classic/datasets", "#dl", "classic datasets kept")
    # VI
    pg.evaluate("()=>fetch('api/auth/lang',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lang:'vi'})})"); ctx.add_cookies([{"name": "aos_lang", "value": "vi", "url": U}])
    go("/projects?p=1", "#rb tr.r", "Tracing (VI)"); ok("VI labels", "Thêm bộ lọc" in pg.inner_text("#addf"), pg.inner_text("#addf"))
    go("/settings?s=keys", "#setnav", "Settings (VI)"); ok("VI settings nav", "TRUY CẬP VÀ BẢO MẬT" in pg.inner_text("#setnav").upper() and "Quay lại Agent OS" in pg.inner_text("#setnav"))
    go("/overview?welcome=1", "#wyes", "Welcome (VI)"); ok("VI welcome", "Bạn đã có agent chưa?" in pg.inner_text("body"))
    for pth in ["/engine", "/evaluators", "/annotation", "/context", "/gateway", "/datasets", "/playground", "/deployments?cli=1"]:
        go(pth, "#content", f"VI {pth}")
    pg.evaluate("()=>fetch('api/auth/lang',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lang:'en'})})")
    me = pg.evaluate("()=>fetch('api/auth/me').then(r=>r.json())"); ok("language saved per user", me.get("lang") == "en", me.get("lang"))
print(f"\nTOTAL {sum(R.values())}/{len(R)}")
